package sound

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
)

// version is part of every file name. Bump it when the synthesis changes,
// so files generated by older builds are not reused.
const version = 1

// System plays effects through the operating system's audio player:
// pw-play, paplay or aplay on Linux, afplay on macOS, PowerShell on
// Windows. The WAV files are written to a directory on first use. When no
// player is found, it stays silent.
type System struct {
	dir string

	once  sync.Once
	cmd   []string // player command; the file path is appended
	files [numEffects]string

	// Test hooks.
	goos     string
	lookPath func(string) (string, error)
	start    func(name string, args ...string) error
}

// NewSystem returns a player that keeps its WAV files in dir.
func NewSystem(dir string) *System {
	return &System{
		dir:      dir,
		goos:     runtime.GOOS,
		lookPath: exec.LookPath,
		start: func(name string, args ...string) error {
			c := exec.Command(name, args...)
			if err := c.Start(); err != nil {
				return err
			}
			go func() { _ = c.Wait() }() // reap the process; its exit code is irrelevant
			return nil
		},
	}
}

// Play starts the effect and returns at once. The first call also finds
// the player and writes the sound files, in the background.
func (s *System) Play(e Effect) {
	if e >= numEffects {
		return
	}
	go func() {
		s.once.Do(s.prepare)
		if s.cmd == nil || s.files[e] == "" {
			return
		}
		args := append(append([]string(nil), s.cmd[1:]...), s.files[e])
		if s.goos == "windows" {
			// PowerShell takes a script, not a path argument.
			args = append(append([]string(nil), s.cmd[1:]...),
				"(New-Object Media.SoundPlayer '"+strings.ReplaceAll(s.files[e], "'", "''")+"').PlaySync()")
		}
		_ = s.start(s.cmd[0], args...)
	}()
}

// prepare finds the player and writes the WAV files.
func (s *System) prepare() {
	s.cmd = s.findPlayer()
	if s.cmd == nil {
		return
	}
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		s.cmd = nil
		return
	}
	for _, e := range Effects() {
		path := filepath.Join(s.dir, fmt.Sprintf("%s-v%d.wav", e, version))
		if err := writeIfChanged(path, WAV(e)); err == nil {
			s.files[e] = path
		}
	}
}

// findPlayer returns the command line of the first available player.
func (s *System) findPlayer() []string {
	var candidates [][]string
	switch s.goos {
	case "darwin":
		candidates = [][]string{{"afplay"}}
	case "windows":
		candidates = [][]string{{"powershell", "-NoProfile", "-NonInteractive", "-Command"}}
	default:
		candidates = [][]string{{"pw-play"}, {"paplay"}, {"aplay", "-q"}}
	}
	for _, c := range candidates {
		if path, err := s.lookPath(c[0]); err == nil {
			return append([]string{path}, c[1:]...)
		}
	}
	return nil
}

// writeIfChanged writes data to path unless the file already holds it.
// It writes to a temporary file and renames it, so a player never reads a
// half-written file.
func writeIfChanged(path string, data []byte) error {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
		return nil
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".sound-*.wav")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name()) // no-op after a successful rename
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}
